/** name → 定义。★ 未知席位 = undefined（调用方必须显式处理，不许静默降级）。 */
export const SEAT_BY_NAME: Record<string, SeatDef> = Object.fromEntries(
	SEAT_DEFS.map((s) => [s.name, s]),
);
